// Режем документ на фрагменты с перекрытием.
const text = $json.doc_text || '';
const SIZE = 500;     // сколько символов в чанке
const OVERLAP = 80;   // сколько символов перекрытия

// сначала по абзацам, чтобы не рвать смысл посередине
const paras = text.split(/\n{2,}/).map(s => s.trim()).filter(Boolean);

const raw = [];
let buf = '';
for (const p of paras) {
  if (!buf) { buf = p; continue; }
  if ((buf + '\n\n' + p).length <= SIZE) { buf += '\n\n' + p; continue; }
  raw.push(buf);
  buf = p;
}
if (buf) raw.push(buf);

// абзац длиннее чанка — режем принудительно, с перекрытием
const pieces = [];
for (const p of raw) {
  if (p.length <= SIZE) { pieces.push(p); continue; }
  let i = 0;
  while (i < p.length) {
    pieces.push(p.slice(i, i + SIZE));
    if (i + SIZE >= p.length) break;
    i += SIZE - OVERLAP;
  }
}

// перекрытие на стыках: подклеиваем хвост предыдущего фрагмента
const out = pieces.map((p, i) => {
  const tail = i > 0 ? pieces[i - 1].slice(-OVERLAP) : '';
  return { json: { chunk_index: i, text: (tail ? tail + ' ' : '') + p } };
});
return out;

// Собираем все фрагменты в один запрос к модели эмбеддингов.
const chunks = $('Нарезка на чанки').all().map(i => i.json.text);
return [{ json: { texts: chunks, count: chunks.length } }];

// Склеиваем векторы с исходными текстами — в Qdrant поедет и то, и другое.
const texts = $('Собрать пачку').first().json.texts;
const vecs = $json.data.map(d => d.embedding);
if (vecs.length !== texts.length) {
  throw new Error('векторов ' + vecs.length + ', а фрагментов ' + texts.length);
}
const points = texts.map((t, i) => ({
  id: i + 1,
  vector: vecs[i],
  payload: { text: t, chunk_index: i, source: 'knowledge-base.md' },
}));
return [{ json: { points, count: points.length, dim: vecs[0].length } }];

const r = $json.result || $json;
return [{ json: {
  загружено_фрагментов: $('Собрать точки').first().json.count,
  размерность: $('Собрать точки').first().json.dim,
  коллекция: 'n8n-lab-kb',
  статус: r.status || 'ok',
  время_мс: r.time,
} }];
